    const container = document.getElementById('tile-container');
    for (let i = 0; i < 5; i++) { // Repeat the tile 5 times
        const tile = document.createElement('div');
        tile.className = 'tile';
        container.appendChild(tile);
    }
}

createTile();
```

In this example, the `createTile` function creates five div elements with the class `tile` and appends them to the `tile-container`.

